&lt;ul&gt;
&lt;li style=&quot;font-weight: 400;&quot;&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Frontend: Typescript, React, GraphQL (Apollo Server)&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-weight: 400;&quot;&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Backend: Typescript, Express, GraphQL (Apollo Client), Node.js, PostgreSQL&lt;/span&gt;&lt;/li&gt;
